#!/usr/bin/env python3
"""Independent re-verification of report.json against network.json."""
import json

T_EPS = 1e-4

data = json.load(open("network.json"))
rep = json.load(open("report.json"))
T = data["time_periods"]
th = data["thermal_generators"]
rn = data["renewable_generators"]
dem, res = data["demand"], data["reserves"]

rep_th = {g["name"]: g for g in rep["thermal_generators"]}
rep_rn = {g["name"]: g for g in rep["renewable_generators"]}
fails = []

# structure
assert rep["case_name"] == "unit_commitment_schedule"
assert set(rep_th) == set(th), "thermal names mismatch"
assert set(rep_rn) == set(rn), "renewable names mismatch"
for g in rep["thermal_generators"]:
    for k in ("commitment", "production_MW", "reserve_MW", "startup", "shutdown"):
        assert len(g[k]) == T, (g["name"], k)
for g in rep["renewable_generators"]:
    assert len(g["production_MW"]) == T
assert [h["hour"] for h in rep["hourly_summary"]] == list(range(1, T + 1))

def u_prev(i, t, u_seq):
    return th[i]["unit_on_t0"] if t == 0 else u_seq[t - 1]

max_bal = 0.0
max_short = 0.0
for t in range(T):
    tp = sum(rep_th[i]["production_MW"][t] for i in th)
    rp = sum(rep_rn[n]["production_MW"][t] for n in rn)
    sr = sum(rep_th[i]["reserve_MW"][t] for i in th)
    bal = tp + rp - dem[t]
    max_bal = max(max_bal, abs(bal))
    max_short = max(max_short, max(0.0, res[t] - sr))
    hs = rep["hourly_summary"][t]
    if abs(hs["thermal_generation_MW"] - tp) > T_EPS or \
       abs(hs["renewable_generation_MW"] - rp) > T_EPS or \
       abs(hs["demand_MW"] - dem[t]) > T_EPS or \
       abs(hs["reserve_requirement_MW"] - res[t]) > T_EPS or \
       abs(hs["scheduled_spinning_reserve_MW"] - sr) > T_EPS:
        fails.append(f"hourly_summary mismatch at hour {t+1}")
    if abs(bal) > T_EPS:
        fails.append(f"balance hour {t+1}: {bal}")
    if res[t] - sr > T_EPS:
        fails.append(f"reserve shortfall hour {t+1}: {res[t]-sr}")

nstart = nshut = 0
cost = 0.0
for i, g in th.items():
    R = rep_th[i]
    u_seq = R["commitment"]
    pmin, pmax = g["power_output_minimum"], g["power_output_maximum"]
    rul, rdl = g["ramp_up_limit"], g["ramp_down_limit"]
    sul, sdl = g["ramp_startup_limit"], g["ramp_shutdown_limit"]
    tup, tdn = g["time_up_minimum"], g["time_down_minimum"]
    on0, p0 = g["unit_on_t0"], g["power_output_t0"]
    pts = g["piecewise_production"]
    tiers = sorted(g["startup"], key=lambda z: z["lag"])
    if g["must_run"] and any(v != 1 for v in u_seq):
        fails.append(f"must_run violated: {i}")
    for t in range(T):
        pv, rv, uv = R["production_MW"][t], R["reserve_MW"][t], u_seq[t]
        sv, dv = R["startup"][t], R["shutdown"][t]
        up = u_prev(i, t, u_seq)
        # logic
        if sv != (1 if (uv == 1 and up == 0) else 0):
            fails.append(f"startup flag {i} t{t+1}")
        if dv != (1 if (uv == 0 and up == 1) else 0):
            fails.append(f"shutdown flag {i} t{t+1}")
        nstart += sv
        nshut += dv
        # limits
        if uv == 1:
            if pv < pmin - T_EPS or pv > pmax + T_EPS:
                fails.append(f"limits {i} t{t+1}: {pv}")
            if pv + rv > pmax + T_EPS or rv > rul + T_EPS:
                fails.append(f"reserve deliverability {i} t{t+1}")
        else:
            if abs(pv) > T_EPS or abs(rv) > T_EPS:
                fails.append(f"off-unit output {i} t{t+1}")
        # ramping
        pp = p0 if t == 0 else R["production_MW"][t - 1]
        if up == 1 and uv == 1:
            if pv - pp > rul + T_EPS or pp - pv > rdl + T_EPS:
                fails.append(f"ramp {i} t{t+1}: {pp}->{pv}")
        elif up == 0 and uv == 1:
            if pv > sul + T_EPS:
                fails.append(f"startup ramp {i} t{t+1}: {pv}")
        elif up == 1 and uv == 0:
            if pp > sdl + T_EPS:
                fails.append(f"shutdown ramp {i} t{t+1}: {pp}")
        # cost
        if uv == 1:
            c = None
            for a, b in zip(pts, pts[1:]):
                if a["mw"] - T_EPS <= pv <= b["mw"] + T_EPS:
                    frac = (pv - a["mw"]) / (b["mw"] - a["mw"])
                    c = a["cost"] + frac * (b["cost"] - a["cost"])
                    break
            if c is None:
                fails.append(f"cost interp {i} t{t+1}: {pv}")
            else:
                cost += c
        if uv == 1 and up == 0:
            # downtime
            D = 0
            k = t - 1
            while k >= 0 and u_seq[k] == 0:
                D += 1
                k -= 1
            if k < 0 and g["unit_on_t0"] == 0:
                D += g["time_down_t0"]
            tc = tiers[-1]["cost"]
            for tier in tiers:
                if D <= tier["lag"]:
                    tc = tier["cost"]
                    break
            cost += tc
    # min up/down
    for t in range(T):
        up = u_prev(i, t, u_seq)
        if u_seq[t] == 1 and up == 0 and t + tup <= T:
            if any(u_seq[k] != 1 for k in range(t, t + tup)):
                fails.append(f"min-up {i} t{t+1}")
        if u_seq[t] == 0 and up == 1 and t + tdn <= T:
            if any(u_seq[k] != 0 for k in range(t, t + tdn)):
                fails.append(f"min-down {i} t{t+1}")
    # initial conditions
    if on0 == 1:
        if u_seq[0] == 1:
            if R["production_MW"][0] - p0 > rul + T_EPS or \
               p0 - R["production_MW"][0] > rdl + T_EPS:
                fails.append(f"initial ramp {i}: {p0}->{R['production_MW'][0]}")
        else:
            if p0 > sdl + T_EPS:
                fails.append(f"initial shutdown ramp {i}")

for n, g in rn.items():
    for t in range(T):
        pv = rep_rn[n]["production_MW"][t]
        if pv < g["power_output_minimum"][t] - T_EPS or \
           pv > g["power_output_maximum"][t] + T_EPS:
            fails.append(f"renew limits {n} t{t+1}: {pv}")

# summary cross-check
s = rep["summary"]
if abs(s["objective_cost"] - cost) > 0.05:
    fails.append(f"objective_cost {s['objective_cost']} vs recomputed {cost:.2f}")
if s["total_startups"] != nstart or s["total_shutdowns"] != nshut:
    fails.append(f"startups/shutdowns {s['total_startups']}/{s['total_shutdowns']} vs {nstart}/{nshut}")
if s["time_periods"] != T or s["num_thermal_generators"] != len(th) or \
   s["num_renewable_generators"] != len(rn):
    fails.append("summary counts mismatch")
if abs(s["max_demand_balance_violation_MW"] - max_bal) > T_EPS:
    fails.append(f"balance violation reported {s['max_demand_balance_violation_MW']} vs {max_bal}")
if abs(s["max_reserve_shortfall_MW"] - max_short) > T_EPS:
    fails.append(f"reserve shortfall reported {s['max_reserve_shortfall_MW']} vs {max_short}")

print(f"recomputed objective cost: {cost:.2f}  (reported {rep['summary']['objective_cost']})")
print(f"max balance violation: {max_bal:.2e}  max reserve shortfall: {max_short:.2e}")
print(f"startups: {nstart}  shutdowns: {nshut}")
if fails:
    print(f"FAIL ({len(fails)} issues):")
    for f in fails[:30]:
        print(" -", f)
else:
    print("ALL CHECKS PASS")

