        if u_seq[t] == 1 and up == 0:
            if any(u_seq[k] != 1 for k in range(t, min(T, t + tup))):
                fails.append(f"min-up {i} t{t+1}")
        if u_seq[t] == 0 and up == 1:
            if any(u_seq[k] != 0 for k in range(t, min(T, t + tdn))):
                fails.append(f"min-down {i} t{t+1}")
    # initial conditions
    if on0 == 1 and u_seq[0] == 1:
        pass  # covered by joint ramp checks
    if on0 == 0 and any(u_seq[k] != 0 for k in range(min(T, tdn - g["time_down_t0"]))):
        fails.append(f"initial min-down {i}")

for n, g in rn.items():
    for t in range(T):
        pv = rep_rn[n]["production_MW"][t]
        if pv < g["power_output_minimum"][t] - T_EPS or \
           pv > g["power_output_maximum"][t] + T_EPS:
            fails.append(f"renew limits {n} t{t+1}: {pv}")

s = rep["summary"]
if abs(s["objective_cost"] - cost) > 0.05:
